function notify(s:string){setToast(s);setTimeout(()=>setToast(''),5500)}async function run(f:()=>Promise<any>){try{return await f()}catch(e:any){notify(e.message)}}async function load(){await run(async()=>{const d=await api('bootstrap');setData(d);setBranding(d.branding||{logo:'',favicon:''});if(location.pathname.startsWith('/tv/')){const n=d.tv.findIndex((v:any)=>v.id===location.pathname.split('/')[2]);if(n>=0)setTvIndex(n);setTimeout(()=>document.getElementById('tv')?.scrollIntoView({block:'center'}),100)}const pid=new URLSearchParams(location.search).get('post');if(pid)setTimeout(()=>document.getElementById('post-'+pid)?.scrollIntoView({block:'center'}),100)})}useEffect(()=>{const params=new URLSearchParams(location.search),reference=params.get('reference');if(params.get('paystack')==='1'&&reference){(async()=>{try{const p=await api('paystack/verify',{reference});await load();notify(p.status==='paid'?'Paystack payment confirmed.':'Payment is still pending. Check your payment history later.');params.delete('paystack');params.delete('reference');params.delete('trxref');history.replaceState(null,'',location.pathname+(params.size?'?'+params.toString():''))}catch(e:any){notify(e.message+' Log in and refresh this page to check again.')}})()}},[]);
useEffect(()=>{load();if(location.pathname.startsWith('/shop/')){setShop(decodeURIComponent(location.pathname.split('/')[2]||''));setPage('Marketplace')}if(new URLSearchParams(location.search).has('product')){setMarketProduct(new URLSearchParams(location.search).get('product')||'');setPage('Marketplace')}if(new URLSearchParams(location.search).has('reset'))setModal('reset')},[]);useEffect(()=>{if(data.branding?.favicon){let link=document.querySelector('link[rel=icon]') as HTMLLinkElement;if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}link.href=data.branding.favicon}},[data.branding?.favicon]);useEffect(()=>{if(data.authenticated&&!data.me&&new URLSearchParams(location.search).has('join'))setModal('signup')},[data.authenticated,data.me]);function gate(){if(!me){setModal(data.authenticated&&!guest?'signup':'login');return false}return true}function profile(p:any){setSelected({...p,...(data.members.find((m:any)=>m.id===p.id)||{})});setModal('profile');if(!p.id.startsWith('demo'))run(async()=>{const d=await api('profile?id='+encodeURIComponent(p.id));setSelected({...d.profile,profilePosts:d.posts,activity:d.activity})})}function go(p:string){if(['Messages','Wallet','Notifications','Admin'].includes(p)&&!gate())return;setPage(p);setMobile(false);if(['Wallet','Notifications'].includes(p))run(async()=>setWallet(await api('wallet')));if(p==='Messages')run(async()=>setChats(await api('chats')));if(p==='Admin')run(async()=>setAdmin(await api('admin')))}
async function duration(f:File){return new Promise<number>((yes,no)=>{const v=document.createElement('video'),u=URL.createObjectURL(f);v.src=u;v.onloadedmetadata=()=>{yes(v.duration);URL.revokeObjectURL(u)};v.onerror=()=>no(Error('Cannot read video'))})}
async function compressVideo(f:File){return new Promise<Blob>((yes,no)=>{const v=document.createElement('video'),u=URL.createObjectURL(f);v.src=u;v.playsInline=true;v.onloadedmetadata=async()=>{try{const c=document.createElement('canvas');c.width=Math.min(960,v.videoWidth);c.height=Math.round(v.videoHeight*c.width/v.videoWidth);const s=c.captureStream(24),ac=new AudioContext(),src=ac.createMediaElementSource(v),dest=ac.createMediaStreamDestination();src.connect(dest);dest.stream.getAudioTracks().forEach(t=>s.addTrack(t));const recorder=new MediaRecorder(s,{mimeType:'video/webm',videoBitsPerSecond:480000,audioBitsPerSecond:48000}),chunks:Blob[]=[];let frame:number;const draw=()=>{c.getContext('2d')!.drawImage(v,0,0,c.width,c.height);frame=requestAnimationFrame(draw)};recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{cancelAnimationFrame(frame);ac.close();s.getTracks().forEach(t=>t.stop());URL.revokeObjectURL(u);const b=new Blob(chunks,{type:'video/webm'});b.size<5000000?yes(b):no(Error('Please choose a shorter video.'))};v.onended=()=>recorder.stop();recorder.start();await v.play();draw()}catch{no(Error('This browser cannot compress this video. Please use a video below 5 MB.'))}}})}
async function upload(f:File,k='post',conversation?:string){let blob:Blob=f;if(f.type.startsWith('image/')){const im=await createImageBitmap(f),c=document.createElement('canvas'),scale=Math.min(1,1600/Math.max(im.width,im.height));c.width=im.width*scale;c.height=im.height*scale;c.getContext('2d')!.drawImage(im,0,0,c.width,c.height);let quality=.88;do{blob=await new Promise<Blob>(resolve=>c.toBlob(b=>resolve(b!),'image/webp',quality));quality-=.12}while(blob.size>=500000&&quality>.12);im.close();if(blob.size>=500000)throw Error('Choose a smaller photo. Compression exceeded 500 KB.')}if(f.type.startsWith('video/')){const d=await duration(f);if(d>(k==='tv'?600:60))throw Error(k==='tv'?'TV episodes must be up to 10 minutes.':k==='chat'?'Chat videos must be up to 1 minute.':'Feed videos must be up to 1 minute.');if(k!=='tv'&&f.size>=5000000){notify('Compressing video. Keep this window open.');blob=await compressVideo(f)}}const form=new FormData();form.append('file',blob,f.name);form.append('kind',k);if(conversation)form.append('conversation',conversation);const r=await fetch('/api/upload',{method:'POST',body:form}),d:any=await r.json();if(!r.ok)throw Error(d.error);return d}
