async function like(p:any){if(!gate())return;if(p.id.startsWith('sample'))return notify('Sample post. Share the first real community moment!');await run(async()=>{const d=await api('like',{post:p.id});notify(d.already?'You already liked this post.':'Liked. Thank you for sharing the good energy.');await load()})}async function openComments(p:any){if(!gate())return;if(p.id.startsWith('sample'))return notify('Comments open on real community posts.');setSelected(p);setModal('comments');setReply(null);await run(async()=>setComments(await api('comments?post='+p.id)))}async function share(p?:any){if(!gate())return;await run(async()=>{const url=location.origin+(p?'/?post='+p.id:'/tv/'+(data.tv[tvIndex]?.id||'show'));if(navigator.share)await navigator.share({title:p?'A moment on eConect':'eConect TV',url});else{await navigator.clipboard.writeText(url);notify('Share link copied.')}})}function gift(p:any,k='gift'){if(!gate())return;checkoutId.current=crypto.randomUUID();if(p?.id?.startsWith('demo'))return notify('Gifts are available for registered members. This is a sample profile.');setSelected(p||me);setKind(k);setPack(1);setPayment(null);setSource(k==='topup'||k==='vote'||data.paystackEnabled?'bank':'wallet');setModal('gift')}async function purchase(){setBusy('Processing…');await run(async()=>{if(source==='wallet'&&kind!=='topup'){await api('gift',{recipient:selected.id,coins:pack,kind,coinPrice});setModal('');notify(`${pack} eCoin sent successfully.`);await load()}else if(data.paystackEnabled){const d=await api('paystack/initialize',{id:checkoutId.current,kind:'payment',action:kind,recipient:selected.id,coins:pack,coinPrice});if(d.authorization_url)location.assign(d.authorization_url);else{notify('Payment already confirmed.');await load()}}else setPayment(await api('payment',{recipient:selected.id,coins:pack,kind,coinPrice}))});setBusy('')}
async function startChat(p:any){if(!gate())return;if(p.id.startsWith('demo'))return notify('Invite a friend to start a real conversation. This is a sample member.');await run(async()=>{const c=await api('chat',{recipient:p.id});setChat({...c,person:p});seen.current.clear();setModal('');setPage('Messages');setChats(await api('chats'));setChatData(await api('messages?id='+c.id))})}async function openInquiry(conversation:string,person:any){seen.current.clear();setChatData(null);if(attachment?.preview)URL.revokeObjectURL(attachment.preview);setAttachment(null);setChat({id:conversation,person});setModal('');setPage('Messages');await run(async()=>{setChats(await api('chats'));setChatData(await api('messages?id='+encodeURIComponent(conversation)))})}
async function sendChatMedia(){if(!attachment||!chat||busy)return;const a=attachment;if(a.conversation!==chat.id)return notify('Choose the file again for this conversation.');setBusy('Sending…');try{let url=a.url;if(!url){url=(await upload(a.file,'chat',chat.id)).url;setAttachment((v:any)=>v&&v.id===a.id?{...v,url}:v)}await api('message',{conversation:chat.id,kind:a.kind,body:url,messageId:a.id});URL.revokeObjectURL(a.preview);setAttachment(null);await refreshChat();await load();notify((a.kind==='image'?1:4)+' point'+(a.kind==='image'?'':'s')+' sent to the other member.')}catch(e:any){notify(e.message)}finally{setBusy('')}}
async function signal(kind:string,body:any){await api('message',{conversation:chat.id,kind,body:JSON.stringify(body)})}function stopCall(){pc.current?.close();pc.current=null;stream.current?.getTracks().forEach(t=>t.stop());setCall(null);connected.current=false}
async function refreshChat(){const d=await api('messages?id='+chat.id);setChatData(d);for(const m of d.messages){if(m.sender===me?.id||seen.current.has(m.id)||!['offer','answer','ice','hangup'].includes(m.kind))continue;seen.current.add(m.id);const val=JSON.parse(m.body);if(m.kind==='offer')setIncoming(val);if(m.kind==='answer'&&pc.current)await pc.current.setRemoteDescription(val);if(m.kind==='ice'&&pc.current?.remoteDescription)await pc.current.addIceCandidate(val).catch(()=>{});if(m.kind==='hangup'){stopCall();setIncoming(null)}}}
useEffect(()=>{if(page!=='Messages'||!chat)return;refreshChat().catch(()=>{});const t=setInterval(()=>refreshChat().catch(()=>{}),2500);return()=>clearInterval(t)},[page,chat?.id,me?.id]);
async function callSetup(video:boolean){const s=await navigator.mediaDevices.getUserMedia({audio:true,video});stream.current=s;const connection=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});pc.current=connection;s.getTracks().forEach(t=>connection.addTrack(t,s));connection.onicecandidate=e=>{if(e.candidate)signal('ice',e.candidate.toJSON()).catch(()=>{})};connection.ontrack=e=>{if(remote.current)remote.current.srcObject=e.streams[0]};connection.onconnectionstatechange=()=>{if(connection.connectionState==='connected'){setCall({video,status:'Connected'});connected.current=true;if(chatData?.conversation?.starter===me.id)api('call-start',{conversation:chat.id}).catch(()=>{})}if(connection.connectionState==='failed'){notify('Connection failed. Please try again.');stopCall()}};setCall({video,status:'Connecting…'});setTimeout(()=>{if(local.current)local.current.srcObject=s},100);return connection}
