async function record(){if(recording)return;await run(async()=>{const s=await navigator.mediaDevices.getUserMedia({audio:true}),r=new MediaRecorder(s),chunks:Blob[]=[];rec.current=r;recTime.current=Date.now();r.ondataavailable=e=>chunks.push(e.data);r.onstop=()=>{s.getTracks().forEach(t=>t.stop());setRecording(false);const b=new Blob(chunks,{type:r.mimeType});setVoice({blob:b,url:URL.createObjectURL(b),duration:Math.min(60,Math.max(1,Math.ceil((Date.now()-recTime.current)/1000)))})};r.start();setRecording(true);setTimeout(()=>{if(r.state==='recording')r.stop()},60000)})}async function sendVoice(){setBusy('Sending…');await run(async()=>{const u=await upload(new File([voice.blob],'voice.webm',{type:voice.blob.type}),'voice');await api('message',{conversation:chat.id,kind:'voice',body:u.url,duration:voice.duration});setVoice(null);await refreshChat();await load()});setBusy('')}
useEffect(()=>{if(!me?.id)return;const refresh=()=>api('balance').then(b=>{setData((d:any)=>({...d,me:{...d.me,balance:b.balance,bonus:b.bonus}}));setWallet((w:any)=>({...w,balance:b.balance,bonus:b.bonus,total:b.total}))}).catch(()=>{});const onVisible=()=>{if(document.visibilityState==='visible')refresh()};const timer=setInterval(refresh,20000);document.addEventListener('visibilitychange',onVisible);return()=>{clearInterval(timer);document.removeEventListener('visibilitychange',onVisible)}},[me?.id]);
